<script setup lang="ts">
import SelectField from './SelectField.vue';
import {ref,watch,nextTick} from 'vue';import {router,useForm,usePage} from '@inertiajs/vue3';
import Modal from './Modal.vue';import DateField from './DateField.vue';import Pagination from './Pagination.vue';
import LoadingState from './LoadingState.vue';
import {json,dateLabel} from '../lib/format';
const props=defineProps<{id:string;catalog:any}>();const emit=defineEmits<{close:[]}>();
const modal=ref<InstanceType<typeof Modal>>();const detail=ref<any>(),error=ref(''),loading=ref(false);const page=usePage<any>();let loadNumber=0;
const form=useForm<any>({command_key:crypto.randomUUID(),lock_version:1,name:'',member_id:null,accounts:[]});
function timestamp(value:string){return value?new Date(value).toLocaleString('en-US',{timeZone:page.props.auth.timezone}):'Never';}
async function load(url?:string,reset=false){const number=++loadNumber;loading.value=true;error.value='';try{const result=await json(url||'/connections/'+props.id);if(number!==loadNumber)return;detail.value=result;const c=result.connection;const dirty=form.isDirty&&!reset;const previous=form.accounts;if(!dirty){form.name=c.name;form.member_id=c.member_id;form.lock_version=c.lock_version;}form.accounts=result.accounts.map((a:any)=>({id:a.id,import_start_date:(dirty?previous.find((p:any)=>p.id===a.id)?.import_start_date:null)||a.import_start_date||result.default_start_date}));if(!dirty)form.defaults();}catch(e:any){if(number===loadNumber)error.value=e.message;}finally{if(number===loadNumber)loading.value=false;}}
watch(()=>props.id,()=>load(),{immediate:true});
function save(){form.patch('/connections/'+props.id,{preserveScroll:true,onSuccess:()=>{form.command_key=crypto.randomUUID();load(undefined,true);},onError:()=>nextTick(()=>document.getElementById('connection-errors')?.focus()),onNetworkError:()=>{error.value='The connection failed. Your changes are still here; try again.';return false;},onHttpException:(r:any)=>{error.value=r.status===409?'Connection changed. Reload before saving.':'Could not save connection.';return false;}});}
function sync(){router.post('/connections/'+props.id+'/sync',{command_key:crypto.randomUUID()},{preserveScroll:true,onSuccess:()=>load(),onError:e=>error.value=Object.values(e).join(' '),onHttpException:()=>{error.value='Confirm all starting dates before syncing, or reconnect if authorization has ended.';return false;}});}
</script>
<template><Modal :open="true" :title="detail?.connection.name||'Connection details'" subtitle="Bank connection · Accounts and import dates" :size="760" ref="modal" :dirty="form.isDirty" :busy="form.processing" @close="emit('close')"><div class="p-6">
 <div v-if="error" role="alert" class="mb-4 text-orange-800">{{error}} <button class="underline" @click="load()">Reload</button></div><LoadingState v-if="!detail" :loading="loading" label="Loading connection"/>
 <template v-else><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><span class="badge" :class="detail.connection.state==='active'?'badge-info':'badge-warning'">{{detail.connection.state.replaceAll('_',' ')}}</span><button v-if="detail.connection.state==='active'" class="btn" @click="sync">Sync now</button><a v-else :href="'/connections/authorize?reconnect='+id" class="btn">Reconnect</a></div><p class="help">Last full successful sync: {{timestamp(detail.connection.last_full_success_at)}}</p><p v-if="detail.connection.latest_error" class="callout callout-warning mt-3">Latest error: {{detail.connection.latest_error.replaceAll('_',' ')}}</p>
 <form id="connection-form" class="mt-5 space-y-5" @submit.prevent="save"><div v-if="form.hasErrors" id="connection-errors" tabindex="-1" role="alert" class="rounded bg-orange-50 p-3 text-warning"><p v-for="(value,key) in form.errors" :key="key">{{value}}</p></div><fieldset class="form-section"><legend>Connection</legend><div class="grid gap-4 sm:grid-cols-2"><div class="field"><label for="connection-name">Name</label><input id="connection-name" v-model="form.name" required maxlength="120"/></div><div class="field"><label for="connection-member">Member · optional</label><SelectField id="connection-member" v-model="form.member_id" :options="[{value:null,label:'Shared household'},...(catalog.members).map((m:any)=>({value:m.id,label:m.nickname}))]"/></div></div></fieldset>
 <h3 class="font-medium">Accounts and import starting dates</h3><p class="help">Defaults use the first day of this month in your profile timezone. New accounts found during later syncs start from their UTC discovery date. Dates are inclusive. Moving a date later keeps existing history; moving it earlier imports available older history on the next sync.</p>
 <div class="overflow-x-auto rounded-md border border-line"><div v-for="(a,index) in detail.accounts" :key="a.id" class="grid min-w-[400px] items-center gap-4 border-b border-line-soft p-4 sm:grid-cols-[minmax(0,1fr)_210px]"><div><p class="font-medium">{{a.name}}</p><p class="help mt-1">Last successful sync: {{timestamp(a.last_success_at)}}<span v-if="a.latest_error" class="text-warning"> · {{a.latest_error.replaceAll('_',' ')}}</span></p></div><div class="field"><label>Import starting date</label><DateField v-model="form.accounts[index].import_start_date" :label="a.name+' import starting date'" required/></div><p v-if="!a.import_start_date" class="help mt-2 sm:col-span-2">Awaiting confirmation before first import.</p></div></div>
 </form>
 <h3 class="mb-3 mt-7 font-medium">Sync history</h3><div v-for="run in detail.runs.data" :key="run.id" class="border-t border-line py-3"><p>{{timestamp(run.created_at)}} · <span class="badge">{{run.state}}</span></p><p v-if="run.error" class="help mt-1 text-warning">{{run.error.replaceAll('_',' ')}}</p><p v-for="result in run.accounts" :key="result.id" class="help mt-1">{{detail.accounts.find((a:any)=>a.id===result.account_id)?.name||'Removed account'}}: {{result.state}} · {{result.imported_count||0}} imported<span v-if="result.error"> · {{result.error.replaceAll('_',' ')}}</span></p></div><Pagination :records="detail.runs" asynchronous @load="load"/>
 </template>
</div><div v-if="detail" class="sticky bottom-0 flex justify-end gap-2 border-t border-line bg-white px-6 py-4"><button class="btn" @click="modal?.close()" :disabled="form.processing">Cancel</button><button form="connection-form" class="btn-primary" :disabled="form.processing">{{form.processing?'Saving…':'Save connection & import dates'}}</button></div></Modal></template>
